export const MAX_CHARGE=1;
export function createFrog(){return{status:'ready',z:0,x:0,speed:0,stamina:100,strokes:0,combo:0,nextHand:0,active:[false,false,false,false],rear:[false,false],charges:[0,0],lastPull:-9,leap:null,message:'Alternate front hands to swim. Hold a rear foot to charge a leap.'}}
export function pull(s,i,now=0){if(s.status!=='playing'||s.leap||i<0||i>1)return false;s.active[i]=true;const gap=now-s.lastPull;if(i===s.nextHand&&gap>.1){s.nextHand=1-i;s.combo=Math.min(12,s.combo+1);s.speed=Math.min(7.5,s.speed+.8+s.combo*.025);s.stamina=Math.min(100,s.stamina+1);s.strokes++;s.lastPull=now;s.message=s.combo>5?'Smooth swimming! Charge a rear leg for a big leap.':'Good pull. Now use the other hand.';return true}s.combo=0;s.speed=Math.max(0,s.speed-.35);s.stamina=Math.max(0,s.stamina-2);s.message=i===s.nextHand?'Slow down—let the hand finish its pull.':'Alternate your front hands.';return false}
export function releaseHand(s,i){if(i>=0&&i<2)s.active[i]=false}
export function pressRear(s,i){if(s.status!=='playing'||s.leap||i<0||i>1)return false;s.rear[i]=true;s.active[i+2]=true;s.message='Leg coiling… release it to leap!';return true}
export function releaseRear(s,i){if(i<0||i>1||!s.rear[i])return false;s.rear[i]=false;s.active[i+2]=false;const power=s.charges[i];s.charges[i]=0;if(s.status!=='playing'||s.leap||power<.1){s.message='Hold that frog leg a little longer.';return false}s.leap={elapsed:0,duration:.48+power*.32,power,side:i};s.speed=Math.min(11,s.speed+1.8+power*4.7);s.stamina=Math.min(100,s.stamina+power*4);s.combo=Math.min(12,s.combo+Math.round(power*2));s.message=power>.75?'MEGA FROG LEAP! Webbed feet deployed.':'Kick! Hold longer for a bigger leap.';return true}
export function cancelControls(s){s.active=[false,false,false,false];s.rear=[false,false];s.charges=[0,0]}
export function currentAt(z){return Math.sin(z*.045)*.48+Math.sin(z*.013)*.22}
export function obstacleAt(index){const z=12+index*13+(index%3)*2;return{z,x:Math.sin(index*2.17)*.72,kind:index%3===0?'log':index%3===1?'lily':'bottle'}}
export function advance(s,elapsed){if(s.status!=='playing')return;const dt=Math.min(.05,Math.max(0,elapsed));for(let i=0;i<2;i++)if(s.rear[i])s.charges[i]=Math.min(MAX_CHARGE,s.charges[i]+dt*.72);if(s.leap){s.leap.elapsed+=dt;if(s.leap.elapsed>=s.leap.duration)s.leap=null}s.speed*=Math.exp(-(s.leap?.power>.6?.18:.48)*dt);s.z+=s.speed*dt;s.x+=currentAt(s.z)*dt*.15;s.x=Math.max(-1.12,Math.min(1.12,s.x));s.stamina=Math.max(0,s.stamina-dt*(s.speed<.5?3.8:.18));if(s.stamina<=0){s.status='over';s.message='Out of steam. The frog is taking a float break.'}}
export function nudge(s,amount){if(s.status==='playing')s.x=Math.max(-1.12,Math.min(1.12,s.x+amount))}
